import "server-only";
import data from "@/data/problems.json";

// Problems are generated by scripts/problems.py (statements, starter code,
// and tests whose expected output comes from a reference solution).

export type Track = "PF" | "OOP" | "DSA";
export type Difficulty = "Easy" | "Medium" | "Hard";

type Case = { input: string; output: string };

type Problem = {
  slug: string;
  title: string;
  track: Track;
  difficulty: Difficulty;
  statement: string;
  input: string;
  output: string;
  constraints: string[];
  hint: string | null;
  sample: Case;
  tests: Case;
  starter: { cpp: string; java: string };
};

/** What the browser is allowed to see: everything except the hidden tests. */
export type PublicProblem = Omit<Problem, "tests">;

const PROBLEMS = data as Problem[];

export const TRACKS: Record<Track, { name: string; course: string; blurb: string }> = {
  PF: {
    name: "Programming Fundamentals",
    course: "CS1002",
    blurb: "Loops, conditions, functions, arrays and strings.",
  },
  OOP: {
    name: "Object Oriented Programming",
    course: "CS1004",
    blurb: "Classes, encapsulation, operator overloading and polymorphism.",
  },
  DSA: {
    name: "Data Structures and Algorithms",
    course: "CS2001",
    blurb: "Stacks, hashing, binary search, sliding windows, BFS and dynamic programming.",
  },
};

export function listProblems(): PublicProblem[] {
  return PROBLEMS.map(({ tests: _tests, ...rest }) => rest);
}

export function getProblem(slug: string): PublicProblem | null {
  const p = PROBLEMS.find((x) => x.slug === slug);
  if (!p) return null;
  const { tests: _tests, ...rest } = p;
  return rest;
}

export function getTests(slug: string): { sample: Case; tests: Case } | null {
  const p = PROBLEMS.find((x) => x.slug === slug);
  return p ? { sample: p.sample, tests: p.tests } : null;
}
